/*
 * Copies the synthetic policy documents of knowledge_base into the web, so a citation in a bot answer can open
 * the cited section.
 *
 *   npm run sync:policies                                  # reads ../../knowledge_base/data/policies
 *   npm run sync:policies -- /path/to/data/policies
 *
 * Writes `src/content/policies/policies.generated.json` (every document split at its ## / ### headings) and
 * `src/content/policies/slugs.ts` (the slugs, light enough to ship with the page). Both are generated: do not edit.
 * Run it again when the policies of knowledge_base change, review the diff, and commit it.
 */
import { mkdir, readFile, readdir, writeFile } from "node:fs/promises";
import path from "node:path";
import { fileURLToPath, pathToFileURL } from "node:url";
import type { PolicyDoc, PolicyIndex } from "../src/lib/policies";

const ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "..");
const DEFAULT_DIR = path.resolve(ROOT, "../../knowledge_base/data/policies");
const OUT_DIR = path.join(ROOT, "src/content/policies");

const SECTION = /^(#{2,3})[ \t]+(.+?)[ \t]*$/;
const TITLE = /^#[ \t]+/;

function frontMatter(text: string): { fields: Record<string, string>; body: string } {
  const lines = text.replace(/\r\n?/g, "\n").split("\n");
  if (lines[0] !== "---") throw new Error("missing front matter");
  const end = lines.indexOf("---", 1);
  if (end === -1) throw new Error("unterminated front matter");
  const fields: Record<string, string> = {};
  for (const line of lines.slice(1, end)) {
    const m = /^([a-z_]+):[ \t]*(.*)$/.exec(line); // top-level keys only; list items are indented
    if (m) fields[m[1]] = m[2].replace(/^(["'])(.*)\1$/, "$2").trim();
  }
  return { fields, body: lines.slice(end + 1).join("\n") };
}

export function parsePolicyFile(text: string): PolicyDoc {
  const { fields, body } = frontMatter(text);
  for (const key of ["slug", "title"]) if (!fields[key]) throw new Error(`missing ${key} in the front matter`);
  if (fields.doc_type !== "technical" && fields.doc_type !== "warranty") {
    throw new Error(`doc_type must be technical or warranty (slug ${fields.slug}, got "${fields.doc_type ?? ""}")`);
  }
  const intro: string[] = [];
  const sections: { heading: string; level: 2 | 3; lines: string[] }[] = [];
  let current = intro;
  let inFence = false;
  for (const line of body.split("\n")) {
    if (line.trimStart().startsWith("```")) inFence = !inFence;
    const section = inFence ? null : SECTION.exec(line);
    if (!inFence && TITLE.test(line)) continue; // the # title is the document's name, already known
    if (section) {
      const entry = { heading: section[2], level: section[1].length as 2 | 3, lines: [] as string[] };
      sections.push(entry);
      current = entry.lines;
    } else {
      current.push(line);
    }
  }
  return {
    slug: fields.slug,
    title: fields.title,
    docType: fields.doc_type,
    intro: intro.join("\n").trim(),
    sections: sections.map(({ heading, level, lines }) => ({ heading, level, body: lines.join("\n").trim() })),
  };
}

export function buildPolicyIndex(files: string[]): PolicyIndex {
  const docs = files.map(parsePolicyFile);
  const seen = new Set<string>();
  for (const doc of docs) {
    if (seen.has(doc.slug)) throw new Error(`duplicate slug ${doc.slug}`);
    seen.add(doc.slug);
  }
  return { docs: docs.sort((a, b) => a.slug.localeCompare(b.slug)) };
}

async function main(argv: string[]): Promise<number> {
  const dir = path.resolve(argv[0] ?? DEFAULT_DIR);
  let names: string[];
  try {
    names = (await readdir(dir)).filter((n) => n.endsWith(".md")).sort();
  } catch {
    console.error(`cannot read ${dir}`);
    return 2;
  }
  try {
    const index = buildPolicyIndex(await Promise.all(names.map((n) => readFile(path.join(dir, n), "utf8"))));
    await mkdir(OUT_DIR, { recursive: true });
    await writeFile(path.join(OUT_DIR, "policies.generated.json"), `${JSON.stringify(index, null, 2)}\n`);
    const slugs = index.docs.map((d) => `  ${JSON.stringify(d.slug)},`).join("\n");
    await writeFile(
      path.join(OUT_DIR, "slugs.ts"),
      `// Generated by \`npm run sync:policies\` (scripts/sync-policies.ts). Do not edit by hand.\nexport const POLICY_SLUGS: readonly string[] = [\n${slugs}\n];\n`,
    );
    console.log(`wrote ${index.docs.length} documents from ${dir}`);
    return 0;
  } catch (err) {
    console.error(err instanceof Error ? err.message : String(err));
    return 1;
  }
}

if (process.argv[1] && import.meta.url === pathToFileURL(process.argv[1]).href) {
  main(process.argv.slice(2)).then((code) => process.exit(code));
}
